'use strict';
(()=>{
 const root=document.getElementById('field-station');if(!root)return;
 const screens={camera:{alt:'Field Station camera snapshot with synchronized RF spectrum and county-level location',caption:'Observe the camera and synchronized RF spectrum in one view.'},review:{alt:'Field Station detection review showing real starred captures and classifications from four models',caption:'Inspect real detections, compare model decisions, and organize human reviews.'},models:{alt:'Field Station experimental model showing decision settings, model structure, and learned weights',caption:'Explore each model’s decision settings, structure, and learned weights.'},metrics:{alt:'Field Station metrics with model rankings, precision, recall, accuracy, and day/night false-positive charts',caption:'Compare precision, recall, accuracy, and false positives over time.'}};
 const tabs=[...root.querySelectorAll('[data-field-screen]')],image=root.querySelector('#field-screen-image'),panel=root.querySelector('#field-screen-panel'),expand=root.querySelector('.field-screen-expand'),dialog=root.querySelector('dialog');let active='review';
 function select(tab){active=tab.dataset.fieldScreen;const screen=screens[active];for(const item of tabs){const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1}image.src='assets/field-station/'+active+'.webp';image.srcset='assets/field-station/'+active+'-small.webp 720w, assets/field-station/'+active+'.webp 1440w';image.alt=screen.alt;panel.setAttribute('aria-labelledby',tab.id);root.querySelector('#field-screen-caption').textContent=screen.caption;expand.setAttribute('aria-label','Enlarge '+tab.textContent+' screenshot');}
 for(const tab of tabs){tab.addEventListener('click',()=>select(tab));tab.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=tabs.indexOf(tab),next=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length];select(next);next.focus()})}
 expand.addEventListener('click',()=>{if(matchMedia('(max-width:760px)').matches){window.open('assets/field-station/'+active+'.webp','_blank','noopener');return}const full=dialog.querySelector('img');full.src='assets/field-station/'+active+'.webp';full.alt=screens[active].alt;dialog.showModal()});dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>expand.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
})();
